            switch (self.code_point) {
'"' => {
_ = try writer.writeAll("Unexpected escaped double quote '\"'");
},
'\'' => {
_ = try writer.writeAll("Unexpected escaped single quote \"'\"");
},
'`' => {
_ = try writer.writeAll("Unexpected escaped backtick '`'");
},
'\\' => {
_ = try writer.writeAll("Unexpected escaped backslash '\\'");
},
